<?php
$value=static function(string $key)use($form):string{return is_scalar($form[$key]??'')?(string)($form[$key]??''):'';};
$rowValue=static function(string $key,int $index,string $default='')use($form):string{return is_scalar($form[$key][$index]??null)?(string)$form[$key][$index]:$default;};
$rowCount=$direct?max(1,min(100,count(is_array($form['concepto']??null)?$form['concepto']:[]))):count($items);
?>
<h2>Preparar datos fiscales</h2><form method="post" id="factura-form"><?=csrf_field()?><input type="hidden" name="accion" value="preparar"><input type="hidden" name="modo" value="<?=$direct?'directa':'documento'?>"><input type="hidden" name="documento_id" value="<?=$docId?>"><input type="hidden" name="factura_id" value="<?=$invoice?(int)$invoice['id']:0?>"><div class="grid">
<?php foreach(['rfc'=>['RFC del receptor',13],'nombre'=>['Nombre fiscal exacto del receptor',254],'cp'=>['Código postal fiscal',5],'regimen'=>['Clave de régimen fiscal',3],'uso'=>['Uso CFDI, ejemplo G03',3]] as $key=>$field):?><label><?=ojr_e($field[0])?><input name="<?=$key?>" maxlength="<?=$field[1]?>" required value="<?=ojr_e($value($key))?>" <?=in_array($key,['rfc','nombre','uso'],true)?'data-uppercase':''?>></label><?php endforeach;?>
<label>Método de pago<select name="metodo" required><option value="">Selecciona</option><?php foreach(['PUE'=>'PUE — pago en una sola exhibición','PPD'=>'PPD — parcialidades o diferido'] as $k=>$label):?><option value="<?=$k?>" <?=$value('metodo')===$k?'selected':''?>><?=ojr_e($label)?></option><?php endforeach;?></select></label>
<label>Forma de pago<select name="forma" required><option value="">Selecciona</option><?php foreach(['01'=>'01 — efectivo','03'=>'03 — transferencia','04'=>'04 — tarjeta de crédito','28'=>'28 — tarjeta de débito','99'=>'99 — por definir (PPD)'] as $k=>$label):?><option value="<?=$k?>" <?=$value('forma')===(string)$k?'selected':''?>><?=ojr_e($label)?></option><?php endforeach;?></select></label></div>
<p>RFC, nombre fiscal, uso y unidad se convierten automáticamente a mayúsculas. Copia los datos de la constancia fiscal del receptor.</p><p>PPD requiere complementos de pago posteriores; este módulo inicial no los emite. Solo se admite MXN e IVA 16%, sin descuentos, retenciones u otros impuestos.</p>
<label><input type="checkbox" name="pagado" value="1" <?=$value('pagado')==='1'?'checked':''?>> Si seleccioné PUE, confirmo que recibí el pago completo.</label><label><input type="checkbox" name="sin_retenciones" value="1" required <?=$value('sin_retenciones')==='1'?'checked':''?>> Confirmé que la operación solo lleva IVA 16%, sin retenciones ni otros impuestos.</label>
<div id="factura-conceptos">
<?php for($i=0;$i<$rowCount;$i++):?><section class="factura-concepto">
<?php if($direct):?><div class="grid"><label>Descripción<input name="concepto[<?=$i?>]" value="<?=ojr_e($rowValue('concepto',$i))?>" maxlength="1000" required></label><label>Cantidad<input name="cantidad[<?=$i?>]" value="<?=ojr_e($rowValue('cantidad',$i,'1'))?>" type="number" min="0.001" max="99999.999" step="0.001" required></label><label>Precio unitario sin IVA (MXN)<input name="precio[<?=$i?>]" value="<?=ojr_e($rowValue('precio',$i))?>" type="number" min="0.01" max="999999999.99" step="0.01" required></label></div>
<?php else:$item=$items[$i];?><strong><?=ojr_e($item['concepto'])?></strong><p>Cantidad: <?=ojr_e($item['cantidad'])?> · Precio: <?=ojr_e($item['precio'])?> · Importe: <?=ojr_e($item['importe'])?></p><?php endif;?>
<div class="grid"><label>Clave SAT de producto o servicio<input name="clave[<?=$i?>]" required pattern="[0-9]{8}" maxlength="8" value="<?=ojr_e($rowValue('clave',$i))?>"></label><label>Clave SAT de unidad<input name="unidad[<?=$i?>]" required pattern="[A-Za-z0-9]{2,3}" maxlength="3" data-uppercase value="<?=ojr_e($rowValue('unidad',$i))?>"></label></div>
<?php if($direct):?><button type="button" data-remove-concept>Quitar concepto</button><?php endif;?></section><?php endfor;?></div>
<?php if($direct):?><button type="button" id="agregar-concepto">Agregar concepto</button><p>El subtotal, IVA y total se calculan al preparar el borrador.</p><?php endif;?><button>Preparar y revisar borrador</button></form>
